package org.unallocated.client.mixin.interfacefx;

import net.minecraft.client.Camera;
import org.spongepowered.asm.mixin.Mixin;
import org.spongepowered.asm.mixin.injection.At;
import org.spongepowered.asm.mixin.injection.Inject;
import org.spongepowered.asm.mixin.injection.callback.CallbackInfoReturnable;
import org.unallocated.client.interfacefx.InterfaceEffects;

@Mixin(Camera.class)
abstract class InterfaceCameraMixin {
    // Camera.update stores this result and passes that field to setupPerspective; getFov is only a reader.
    @Inject(require = 0, method = "calculateFov(F)F", at = @At("RETURN"), cancellable = true)
    private void interface$perceivedFov(float partialTick, CallbackInfoReturnable<Float> cir) {
        cir.setReturnValue(InterfaceEffects.perceivedFov(cir.getReturnValueF()));
    }
}
package org.unallocated.client.mixin.interfacefx;

import net.minecraft.client.Minecraft;
import net.minecraft.client.renderer.LightmapRenderStateExtractor;
import net.minecraft.client.renderer.state.LightmapRenderState;
import org.spongepowered.asm.mixin.Mixin;
import org.spongepowered.asm.mixin.Shadow;
import org.spongepowered.asm.mixin.Unique;
import org.spongepowered.asm.mixin.injection.At;
import org.spongepowered.asm.mixin.injection.Inject;
import org.spongepowered.asm.mixin.injection.callback.CallbackInfo;
import org.unallocated.client.interfacefx.InterfaceEffects;

@Mixin(LightmapRenderStateExtractor.class)
abstract class InterfaceLightmapMixin {
    @Shadow private boolean needsUpdate;
    @Unique private float interface$darkness;
    @Unique private boolean interface$wasActive;

    @Inject(require = 0, method = "extract", at = @At("HEAD"))
    private void interface$updatePerception(LightmapRenderState state, float partialTick, CallbackInfo ci) {
        interface$darkness = InterfaceEffects.perceivedDarkness();
        if (interface$darkness > 0 || interface$wasActive) needsUpdate = true;
        interface$wasActive = interface$darkness > 0;
    }

    @Inject(require = 0, method = "extract", at = @At("RETURN"))
    private void interface$perceivedDarkness(LightmapRenderState state, float partialTick, CallbackInfo ci) {
        if (interface$darkness > 0) {
            float original = state.darknessEffectScale;
            state.darknessEffectScale += interface$darkness * Minecraft.getInstance().options.darknessEffectScale().get().floatValue();
            state.needsUpdate = true;
            InterfaceEffects.applied(InterfaceEffects.Effect.GAMMA, original, state.darknessEffectScale);
        }
    }
}
name: Build

# Real CI runs only on deliverable refs (main, hito branches v*, pull requests), and only on commits that already passed
# a rehearsal. A rehearsal is the same workflow on a temporary rehearsal/* branch: a failing check is recorded in the
# rehearsal-verdict artifact for the worker, and the run itself does not fail (no failure notification). Work in
# progress is backed up to refs/backup/*, which runs nothing. Owner, 2026-10-26: no red run in any CASPIAN project.
on:
  push:
    branches: ['main', 'v[0-9]*', 'rehearsal/**']
  pull_request:

permissions:
  contents: read

jobs:
  build:
    runs-on: ubuntu-24.04
    timeout-minutes: 25
    continue-on-error: ${{ startsWith(github.ref, 'refs/heads/rehearsal/') }}
    strategy:
      fail-fast: false
      matrix:
        # Oldest API must be rejected by Loader; the other three profiles must start.
        api: ['none', '0.153.1+26.3', '0.161.0+26.3', '0.165.0+26.3']
    steps:
      - name: Check out source
        uses: actions/checkout@08c6903cd8c0fde910a37f88322edcfb5dd907a8 # v5.0.0
        with:
          persist-credentials: false

      - name: Set up Java 25
        uses: actions/setup-java@f2beeb24e141e01a676f977032f5a29d81c9e27e # v5.1.0
        with:
          distribution: temurin
          java-version: '25'

      - name: Install Gradle and cache dependencies
        uses: gradle/actions/setup-gradle@4d9f0ba0025fe599b4ebab900eb7f3a1d93ef4c2 # v5.0.0
        with:
          # No wrapper JAR is required; keep in sync with TOOLCHAIN.md.
          gradle-version: '9.8.2'
          # Includes caches/fabric-loom (Minecraft assets, natives and Fabric downloads).
          cache-read-only: ${{ github.event_name != 'push' }}

      - name: Cache Loom project and smoke server downloads
        uses: actions/cache@5a3ec84eff668545956fd18022155c47e93e2684 # v4.2.3
        with:
          path: |
            .gradle/loom-cache
            .tmp/smoke-downloads
          key: minecraft-v1-${{ runner.os }}-${{ runner.arch }}-${{ hashFiles('gradle.properties', 'build.gradle', 'settings.gradle', 'fabric-api-modules.json', 'scripts/smoke_test.py') }}

      - name: Build mod
        run: gradle --daemon --console=plain build clientSmokeJar prepareCoexistApi -PsmokeApiVersion=${{ matrix.api }}

      - name: Verify contract text matches Appendix C
        run: python3 scripts/contract_text.py --check

      - name: Verify installable JAR, mixin packages and write checksum
        id: package
        run: python3 scripts/verify_jar.py

      - name: Verify packaging, smoke and contract orchestration failure paths without Java
        run: python3 -B -m unittest discover -s scripts -p 'test_*.py'

      - name: Smoke test dedicated server (Fabric API ${{ matrix.api }})
        timeout-minutes: 6
        run: python3 scripts/smoke_test.py server --fabric-api-version '${{ matrix.api }}'

      - name: Identify graphics runner image
        id: graphics-image
        run: echo "version=$ImageOS-$ImageVersion" >> "$GITHUB_OUTPUT"

      - name: Cache headless graphics packages
        uses: actions/cache@5a3ec84eff668545956fd18022155c47e93e2684 # v4.2.3
        with:
          path: .tmp/headless-debs/*.deb
          key: graphics-v1-${{ runner.arch }}-${{ steps.graphics-image.outputs.version }}-${{ hashFiles('scripts/install_headless_graphics.sh') }}

      - name: Install headless client graphics
        if: ${{ !cancelled() && steps.package.outcome == 'success' }}
        run: |
          bash scripts/install_headless_graphics.sh

      - name: Smoke test client startup or Loader rejection (Fabric API ${{ matrix.api }})
        if: ${{ !cancelled() && steps.package.outcome == 'success' }}
        timeout-minutes: 10
        env:
          LIBGL_ALWAYS_SOFTWARE: 'true'
          SDL_VIDEODRIVER: x11
          ALSOFT_DRIVERS: 'null'
        run: python3 scripts/smoke_test.py client --fabric-api-version '${{ matrix.api }}'

      - name: Upload smoke diagnostics
        if: always()
        uses: actions/upload-artifact@ea165f8d65b6e75b540449e92b4886f43607fa02 # v4.6.2
        with:
          name: smoke-diagnostics-${{ github.sha }}-${{ matrix.api }}
          include-hidden-files: true
